// ══════════════════════════════════════════════════════════════
//  FONCTION DE SÉLECTION PAR THÈME
//  Appelée depuis index.html
// ══════════════════════════════════════════════════════════════

function getVersetsParTheme(theme) {
  switch(theme) {
    case 'amour':   return VERSETS_AMOUR;
    case 'travail': return VERSETS_TRAVAIL;
    case 'famille': return VERSETS_FAMILLE;
    case 'amitie':  return VERSETS_AMITIE;
    default:        return [...VERSETS_AMOUR, ...VERSETS_TRAVAIL, ...VERSETS_FAMILLE, ...VERSETS_AMITIE];
  }
}
